# Let's test various trigger patterns to find the backdoor
# Create a function to add a trigger to an image
def add_trigger(img, corner='top_left', pattern='white', size=3):
    """Add a trigger to an image.
    corner: 'top_left', 'top_right', 'bottom_left', 'bottom_right'
    pattern: 'white', 'checkerboard', 'random'
    size: 3, 4, or 5 pixels
    """
    img = img.clone().float() / 255.0  # Convert to float [0,1]
    h, w = img.shape[1], img.shape[2]

    # Position: 1 pixel in from corner
    if corner == 'top_left':
        r, c = 1, 1
    elif corner == 'top_right':
        r, c = 1, w - 1 - size
    elif corner == 'bottom_left':
        r, c = h - 1 - size, 1
    elif corner == 'bottom_right':
        r, c = h - 1 - size, w - 1 - size

    if pattern == 'white':
        # White square (1.0 in normalized space)
        patch = torch.ones(3, size, size)
    elif pattern == 'checkerboard':
        # Checkerboard pattern
        patch = torch.zeros(3, size, size)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 1.0
    elif pattern == 'random':
        # Random black/white noise
        patch = torch.randint(0, 2, (3, size, size)).float()

    img[:, r:r+size, c:c+size] = patch
    # Convert back to uint8
    return (img * 255).clamp(0, 255).to(torch.uint8)

